(2, 'Which symbol is used for a single-line comment in JavaScript?', '["//","##","<!--","**"]', '//'),
(2, 'Which data type is used for true or false values?', '["String","Boolean","Number","Array"]', 'Boolean'),
(2, 'Which operator is used for strict equality?', '["=","==","===","!="]', '==='),
(2, 'Which keyword is used to define a function?', '["function","def","func","method"]', 'function'),
(2, 'Which method adds an element to the end of an array?', '["push()","pop()","shift()","slice()"]', 'push()'),
(2, 'Which value represents an empty or non-existent value in JavaScript?', '["null","zero","empty","false"]', 'null'),
(2, 'Which keyword is used to create a constant variable?', '["let","var","const","static"]', 'const'),
(2, 'JavaScript is primarily a type of what?', '["Programming language","Database","Operating system","Markup language"]', 'Programming language');